def solve(grid):
    n = len(grid)
    m = len(grid[0])

    out_n = n * 3
    out_m = m * 3
    output = [[0 for _ in range(out_m)] for _ in range(out_n)]

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                for i in range(n):
                    for j in range(m):
                        output[r * n + i][c * m + j] = grid[i][j]

    return output
